/// IMPORTANT: 'dest_flash' must be 256-byte aligned and 'srce_ram' must be 4-byte aligned ///

Iap_Status iap_sector_write (const void * const dest_flash , void * const srce_ram , Iap_Sector_Wr_Size const wr_size)
{
  UInt32 arg_i [5] , arg_o [5] ;

  arg_i [0] = CMD_COPY_RAM_TO_FLASH ;
  arg_i [1] = (UInt32) dest_flash   ;
  arg_i [2] = (UInt32) srce_ram     ;
  arg_i [3] = (UInt32) wr_size      ;
  arg_i [4] = CPU_CLOCK_HZ /1000    ;

  iap_execute (arg_i , arg_o) ;

  return (Iap_Status) arg_o [0] ;
}

